return [
  {
    json: {
      objectId: "FIN-0001",
      path: "01_Objects/Finance/FIN-0001/object.md",
      field: "status",
      currentValue: null,
      approvedValue: "active",
      approvalStatus: "approved",
      sourceSha: "abc123",
      approvedBy: "manual_review",
      auditStatus: "passed",
      mode: "simulation"
    }
  }
];

const inputItems = $input.all();

const reject = (errorCode, message) => [
  {
    json: {
      workflowId: "WF-0011",
      version: "0.1.0",
      mode: "simulation",
      status: "rejected",
      errorCode,
      message,
      fileChanged: false,
      commitCreated: false,
      pushExecuted: false
    }
  }
];

if (inputItems.length !== 1) {
  return reject(
    "INVALID_INPUT_COUNT",
    "Es muss genau ein Änderungsvorschlag vorliegen."
  );
}

const data = inputItems[0].json;

if (
  !("sourceSha" in data) ||
  typeof data.sourceSha !== "string" ||
  data.sourceSha.trim() === ""
) {
  return reject(
    "SOURCE_SHA_MISSING",
    "Der dokumentierte Ausgangs-SHA fehlt."
  );
}

const requiredFields = [
  "objectId",
  "path",
  "field",
  "currentValue",
  "approvedValue",
  "approvalStatus",
  "sourceSha",
  "approvedBy",
  "auditStatus",
  "mode"
];

for (const fieldName of requiredFields) {
  if (!(fieldName in data)) {
    return reject(
      "MISSING_REQUIRED_FIELD",
      `Das Pflichtfeld "${fieldName}" fehlt.`
    );
  }

  if (
    fieldName !== "currentValue" &&
    (
      data[fieldName] === null ||
      data[fieldName] === undefined ||
      String(data[fieldName]).trim() === ""
    )
  ) {
    return reject(
      "MISSING_REQUIRED_FIELD",
      `Das Pflichtfeld "${fieldName}" enthält keinen zulässigen Wert.`
    );
  }
}

if (data.approvalStatus !== "approved") {
  return reject(
    "APPROVAL_REQUIRED",
    "Der Änderungsvorschlag ist nicht freigegeben."
  );
}

if (data.auditStatus !== "passed") {
  return reject(
    "AUDIT_NOT_PASSED",
    "Der Audit wurde nicht bestanden."
  );
}

if (data.mode !== "simulation") {
  return reject(
    "INVALID_MODE",
    "WF-0011 v0.1.0 darf ausschließlich im Modus simulation ausgeführt werden."
  );
}

const objectIdPattern = /^[A-Z][A-Z0-9]*-\d{4}$/;

if (!objectIdPattern.test(data.objectId)) {
  return reject(
    "INVALID_OBJECT_ID",
    "Die Objekt-ID entspricht nicht dem JaMoKo-ID-Schema."
  );
}

const pathIsSafe =
  typeof data.path === "string" &&
  data.path.endsWith(".md") &&
  !data.path.startsWith("/") &&
  !data.path.startsWith("~") &&
  !data.path.includes("..") &&
  !data.path.includes("\\") &&
  !data.path.includes("://") &&
  !data.path.includes("\0");

if (!pathIsSafe) {
  return reject(
    "INVALID_PATH",
    "Der Zielpfad ist ungültig oder unsicher."
  );
}

const allowedFields = [
  "status",
  "name",
  "description",
  "version"
];

if (!allowedFields.includes(data.field)) {
  return reject(
    "INVALID_FIELD",
    "Das Zielfeld ist ungültig oder nicht zugelassen."
  );
}


const changePlan = {
  operation: "replace_field_value",
  objectId: data.objectId,
  path: data.path,
  field: data.field,
  from: data.currentValue,
  to: data.approvedValue,
  sourceSha: data.sourceSha
};

const patchPreview = {
  format: "structured_preview",
  target: data.path,
  field: data.field,
  before: data.currentValue,
  after: data.approvedValue,
  applied: false
};

const patchValid =
  changePlan.objectId === data.objectId &&
  changePlan.path === data.path &&
  changePlan.field === data.field &&
  changePlan.to === data.approvedValue &&
  patchPreview.applied === false;

if (!patchValid) {
  return reject(
    "PATCH_VALIDATION_FAILED",
    "Die simulierte Änderung erfüllt die Sicherheitsbedingungen nicht."
  );
}

return [
  {
    json: {
      workflowId: "WF-0011",
      version: "0.1.0",
      mode: "simulation",
      status: "simulated",
      objectId: data.objectId,
      path: data.path,
      field: data.field,
      currentValue: data.currentValue,
      approvedValue: data.approvedValue,
      sourceSha: data.sourceSha,
      approvedBy: data.approvedBy,
      auditStatus: data.auditStatus,
      changePlan,
      patchPreview,
      patchValid: true,
      fileChanged: false,
      commitCreated: false,
      pushExecuted: false
    }
  }
];
